// Changes: new, the prototypes of the ARG_LIST, INLINE_VALUE and IF_INLINE
// callbacks.
/**
 * @brief ARG_LIST -> INLINE_VALUE ARG_TAIL | ε, the arguments of a call.
 *
 * Called by the precedence parser after the `(` of a call, with the current
 * token being the first token of the first argument or the closing `)`.
 * Attaches every argument to parent, the CALL node, and leaves the closing `)`
 * current for the caller. A trailing comma before `)` is accepted.
 *
 * @param[in,out] ctx Non-null pointer to an initialized context
 * @param[in,out] parser Parser state
 * @param[in,out] parent The CALL node, owned by the precedence stack
 */
void parse_arg_list(Ctx* ctx, Parser* parser, AstNode* parent);

/**
 * @brief INLINE_VALUE -> EXPR | IF_INLINE, one full value.
 *
 * Calls the precedence parser with its own frame on the shared precedence stack
 * and attaches the value to parent; for `if` it calls parse_if_inline.
 *
 * @param[in,out] ctx Non-null pointer to an initialized context
 * @param[in,out] parser Parser state
 * @param[in,out] parent Node the value is attached to
 */
void parse_inline_value(Ctx* ctx, Parser* parser, AstNode* parent);

/**
 * @brief IF_INLINE -> IF EXPR THEN INLINE_VALUE ELSE INLINE_VALUE, an if
 * expression.
 *
 * Called by the precedence parser for `(` followed by `if`, with the current
 * token being the `if` and a NONE holder node owned by the precedence stack as
 * parent; the precedence parser detaches the IF from the holder afterwards.
 * Attaches the IF, flagged AST_FLAG_EXPR, to parent and leaves the token after
 * its else value current (the closing `)` for the caller).
 *
 * @param[in,out] ctx Non-null pointer to an initialized context
 * @param[in,out] parser Parser state
 * @param[in,out] parent Node the IF is attached to
 */
void parse_if_inline(Ctx* ctx, Parser* parser, AstNode* parent);

